import sqlite3

def connect(path):
    db=sqlite3.connect(path,timeout=2)
    db.execute('PRAGMA foreign_keys=ON')
    return db

def publish_export(path,scope,owner,name,value):
    with connect(path) as db:
        db.execute('BEGIN IMMEDIATE')
        old=db.execute('SELECT owner,value FROM exports WHERE scope=? AND name=?',(scope,name)).fetchone()
        if old is None:db.execute('INSERT INTO exports VALUES(?,?,?,?)',(scope,name,owner,value))
        else:
            if old[0]!=owner:raise ValueError('another owner already exports this name in this scope')
            used=db.execute('SELECT count(*) FROM imports WHERE scope=? AND export_name=?',(scope,name)).fetchone()[0]
            if used and old[1]!=value:raise ValueError('cannot modify imported export value')
            db.execute('UPDATE exports SET value=? WHERE scope=? AND name=?',(value,scope,name))

def switch_import(path,scope,consumer,new_export,verify):
    with connect(path) as db:
        db.execute('BEGIN IMMEDIATE')
        old=db.execute('SELECT export_name FROM imports WHERE scope=? AND consumer=?',(scope,consumer)).fetchone()
        value=db.execute('SELECT value FROM exports WHERE scope=? AND name=?',(scope,new_export)).fetchone()
        if old is None or value is None:raise ValueError('consumer and new export must exist in the same scope')
        if verify(value[0]) is not True:raise ValueError('new resource not verified')
        db.execute('UPDATE imports SET export_name=? WHERE scope=? AND consumer=?',(new_export,scope,consumer))

def retire_export(path,scope,owner,name):
    with connect(path) as db:
        db.execute('BEGIN IMMEDIATE')
        row=db.execute('SELECT owner FROM exports WHERE scope=? AND name=?',(scope,name)).fetchone()
        if row is None or row[0]!=owner:raise ValueError('unknown or unowned export')
        if db.execute('SELECT count(*) FROM imports WHERE scope=? AND export_name=?',(scope,name)).fetchone()[0]:raise ValueError('imports must be zero before retirement')
        db.execute('DELETE FROM exports WHERE scope=? AND name=?',(scope,name))
